// Main Zod Schema


export type EmailNotificationProps = Record<string, any>;

const EmailNotification: React.FC<EmailNotificationProps> = ({
  backgroundColor = "#fbfbf9",
  transparentBackground = false,
  durationInSeconds = 10,
  senderName = "Ralph @ Aon",
  senderHandle = "Ralph.Aon@aon.com",
  subject = "Quick request — AI chat icon",
  greeting = "Hey Taylor,",
  goal1 = "We need an AI chatbot icon.",
  goal2 = "Familiar to the Everyday family,",
  goal3 = "Scalable across client colors,",
  goal4 = "Speaking to a human — not AI.",
  yellowHighlight = "#fef08a",
  mintHighlight = "#a7f3d0",
  coralHighlight = "#fecaca",
  skyHighlight = "#bae6fd",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency handling
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timings & Frame Calculations
  const startExpandFrame = Math.floor(1.8 * fps);

  // ACT 1: Banner Springs In
  const entrySpring = spring({
    frame,
    fps,
    config: {
      damping: 14,
      mass: 0.8,
      stiffness: 90,
    },
  });

  // ACT 2: Banner Expands
  const expandSpring = spring({
    frame: Math.max(0, frame - startExpandFrame),
    fps,
    config: {
      damping: 18,
      mass: 1.0,
      stiffness: 80,
    },
  });

  const expandProgress = frame < startExpandFrame ? 0 : expandSpring;

  // Responsive Dimensions & Layout Logic (Scaled up for maximum visual presence)
  const initialWidth = Math.min(1200, width * 0.9);
  const initialHeight = 200;
  const initialTop = height * 0.15;
  const initialLeft = (width - initialWidth) / 2;

  const finalWidth = Math.min(1500, width * 0.92);
  const finalHeight = Math.min(960, height * 0.88);
  const finalTop = (height - finalHeight) / 2;
  const finalLeft = (width - finalWidth) / 2;

  // Interpolated Card Bounds
  const currentWidth = interpolate(expandProgress, [0, 1], [initialWidth, finalWidth]);
  const currentHeight = interpolate(expandProgress, [0, 1], [initialHeight, finalHeight]);
  const entryY = interpolate(entrySpring, [0, 1], [-320, initialTop]);
  const currentTop = interpolate(expandProgress, [0, 1], [entryY, finalTop]);
  const currentLeft = interpolate(expandProgress, [0, 1], [initialLeft, finalLeft]);
  
  const currentScale = interpolate(entrySpring, [0, 1], [0.85, 1]);
  const cardOpacity = interpolate(entrySpring, [0, 0.4], [0, 1], { extrapolateRight: "clamp" });
  const cardBorderRadius = interpolate(expandProgress, [0, 1], [32, 24]);

  // Content Cross-fade Opacities
  const collapsedOpacity = interpolate(expandProgress, [0, 0.35], [1, 0], { extrapolateRight: "clamp" });
  const expandedOpacity = interpolate(expandProgress, [0.45, 1], [0, 1], { extrapolateLeft: "clamp" });

  // Avatar / Icon bounce
  const iconScale = interpolate(entrySpring, [0.4, 0.8], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const avatarScale = interpolate(expandProgress, [0.4, 0.8], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // ACT 3: Typing & Highlights Specifications (Up-scaled layouts)
  const bodyLines = [
    {
      text: greeting,
      startSec: 3.2,
      durationSec: 0.5,
      highlight: false,
      highlightColor: "",
      highlightStartSec: 0,
      rotateDeg: 0,
      borderRadius: "",
      isGoal: false,
    },
    {
      text: goal1,
      startSec: 3.9,
      durationSec: 0.8,
      highlight: true,
      highlightColor: yellowHighlight,
      highlightStartSec: 4.2,
      rotateDeg: -0.6,
      borderRadius: "20px 6px 18px 4px / 6px 14px 4px 18px",
      isGoal: true,
    },
    {
      text: goal2,
      startSec: 5.1,
      durationSec: 0.9,
      highlight: true,
      highlightColor: mintHighlight,
      highlightStartSec: 5.4,
      rotateDeg: 0.5,
      borderRadius: "22px 8px 15px 6px / 8px 18px 6px 12px",
      isGoal: true,
    },
    {
      text: goal3,
      startSec: 6.3,
      durationSec: 0.8,
      highlight: true,
      highlightColor: coralHighlight,
      highlightStartSec: 6.6,
      rotateDeg: -0.4,
      borderRadius: "15px 18px 12px 20px / 12px 8px 18px 6px",
      isGoal: true,
    },
    {
      text: goal4,
      startSec: 7.5,
      durationSec: 0.9,
      highlight: true,
      highlightColor: skyHighlight,
      highlightStartSec: 7.8,
      rotateDeg: 0.7,
      borderRadius: "20px 8px 22px 6px / 6px 14px 8px 18px",
      isGoal: true,
    },
  ];

  // Typing helper function
  const getTypedText = (text: string, startFrame: number, durationFrames: number, currentFrame: number) => {
    if (currentFrame < startFrame) return "";
    const progress = (currentFrame - startFrame) / durationFrames;
    if (progress >= 1) return text;
    const charsToShow = Math.floor(progress * text.length);
    return text.substring(0, charsToShow);
  };

  // Sweep helper function using physical spring
  const getSweepProgress = (startSec: number, currentFrame: number, fps: number) => {
    const startFrame = startSec * fps;
    if (currentFrame < startFrame) return 0;
    return spring({
      frame: currentFrame - startFrame,
      fps,
      config: {
        damping: 15,
        stiffness: 80,
        mass: 0.8,
      },
    });
  };

  // Cursor Blinker logic
  const showCursor = Math.floor(frame / (fps / 2)) % 2 === 0;

  // Active Line index for Cursor follow
  let activeLineIndex = -1;
  if (frame >= 7.5 * fps) {
    activeLineIndex = 4;
  } else if (frame >= 6.3 * fps) {
    activeLineIndex = 3;
  } else if (frame >= 5.1 * fps) {
    activeLineIndex = 2;
  } else if (frame >= 3.9 * fps) {
    activeLineIndex = 1;
  } else if (frame >= 3.2 * fps) {
    activeLineIndex = 0;
  }

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      {/* Decorative Blueprint Background Grid */}
      {!transparentBackground && (
        <>
          <div
            style={{
              position: "absolute",
              inset: 0,
              background: `radial-gradient(circle at 50% 30%, #ffffff 0%, ${backgroundColor} 100%)`,
              transition: "none",
            }}
          />
          <div
            style={{
              position: "absolute",
              inset: 0,
              backgroundImage: "radial-gradient(#e2e8f0 2px, transparent 2px)",
              backgroundSize: "32px 32px",
              opacity: 0.5,
              transition: "none",
            }}
          />
        </>
      )}

      {/* Main Notification Card */}
      <div
        style={{
          position: "absolute",
          top: currentTop,
          left: currentLeft,
          width: currentWidth,
          height: currentHeight,
          backgroundColor: "#ffffff",
          borderRadius: cardBorderRadius,
          boxShadow: "0 32px 72px rgba(15, 23, 42, 0.08), 0 8px 24px rgba(15, 23, 42, 0.04)",
          border: "1px solid rgba(15, 23, 42, 0.08)",
          transform: `scale(${currentScale})`,
          opacity: cardOpacity,
          overflow: "hidden",
          transition: "none",
        }}
      >
        {/* ACT 1: Collapsed UI (Notification Pill) */}
        {collapsedOpacity > 0 && (
          <div
            style={{
              position: "absolute",
              inset: 0,
              opacity: collapsedOpacity,
              display: "flex",
              alignItems: "center",
              padding: "0 48px",
              justifyContent: "space-between",
              transition: "none",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: 26 }}>
              <div
                style={{
                  width: 92,
                  height: 92,
                  borderRadius: 24,
                  backgroundColor: "#f5f3ff",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  border: "1px solid #ddd6fe",
                  transform: `scale(${iconScale})`,
                  transition: "none",
                }}
              >
                <EnvelopeIcon size={44} color="#4f46e5" />
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                <span style={{ fontWeight: 600, fontSize: 30, color: "#0f172a", letterSpacing: "-0.01em" }}>
                  {senderName}
                </span>
                <span style={{ fontSize: 24, color: "#64748b", fontWeight: 400 }}>
                  {subject}
                </span>
              </div>
            </div>
            <div style={{ fontSize: 22, color: "#94a3b8", fontWeight: 500 }}>
              now
            </div>
          </div>
        )}

        {/* ACT 2: Expanded UI (Minimal Email Viewer) */}
        {expandedOpacity > 0 && (
          <div
            style={{
              position: "absolute",
              inset: 0,
              opacity: expandedOpacity,
              display: "flex",
              flexDirection: "column",
              padding: "44px 64px",
              transition: "none",
            }}
          >
            {/* Header: OS window controls */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                marginBottom: 32,
                transition: "none",
              }}
            >
              <div style={{ display: "flex", gap: 14 }}>
                <div style={{ width: 20, height: 20, borderRadius: "50%", backgroundColor: "#ef4444", opacity: 0.8 }} />
                <div style={{ width: 20, height: 20, borderRadius: "50%", backgroundColor: "#f59e0b", opacity: 0.8 }} />
                <div style={{ width: 20, height: 20, borderRadius: "50%", backgroundColor: "#10b981", opacity: 0.8 }} />
              </div>
              <div style={{ fontSize: 18, color: "#94a3b8", fontWeight: 600, letterSpacing: "0.08em" }}>
                INBOX — MAIL ARCHIVE
              </div>
              <div style={{ width: 72 }} />
            </div>

            <div style={{ height: "2px", backgroundColor: "#f1f5f9", width: "100%", marginBottom: 28 }} />

            {/* Sender block */}
            <div style={{ display: "flex", alignItems: "center", gap: 24, marginBottom: 28, transition: "none" }}>
              <Avatar size={80} scale={avatarScale} />
              <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                <span style={{ fontWeight: 600, fontSize: 28, color: "#0f172a", letterSpacing: "-0.01em" }}>
                  {senderName}
                </span>
                <span style={{ fontSize: 20, color: "#64748b", fontWeight: 400 }}>
                  to Taylor • {senderHandle}
                </span>
              </div>
            </div>

            <div style={{ height: "2px", backgroundColor: "#f1f5f9", width: "100%", marginBottom: 32 }} />

            {/* Subject Line */}
            <div style={{ fontWeight: 600, fontSize: 40, color: "#0f172a", marginBottom: 36, letterSpacing: "-0.01em" }}>
              {subject}
            </div>

            {/* ACT 3: Animated Email Body */}
            <div style={{ display: "flex", flexDirection: "column", gap: 24, transition: "none" }}>
              {bodyLines.map((line, index) => {
                const shouldRender = frame >= line.startSec * fps;
                if (!shouldRender) return null;

                const currentTyped = getTypedText(line.text, line.startSec * fps, line.durationSec * fps, frame);
                const isCurrentActive = activeLineIndex === index;
                const sweepProgress = getSweepProgress(line.highlightStartSec, frame, fps);

                return (
                  <div
                    key={index}
                    style={{
                      display: "flex",
                      alignItems: "flex-start",
                      marginLeft: line.isGoal ? 48 : 0,
                      lineHeight: 1.5,
                      fontSize: line.isGoal ? 34 : 38,
                      color: "#334155",
                      fontWeight: 400,
                      transition: "none",
                    }}
                  >
                    {line.isGoal && (
                      <span style={{ marginRight: 18, color: "#cbd5e1", userSelect: "none" }}>
                        •
                      </span>
                    )}
                    <div style={{ position: "relative", display: "inline-block" }}>
                      <span
                        style={{
                          position: "relative",
                          zIndex: 10,
                          display: "inline-flex",
                          alignItems: "center",
                          whiteSpace: "pre-wrap",
                        }}
                      >
                        {currentTyped}
                        {isCurrentActive && showCursor && (
                          <span
                            style={{
                              display: "inline-block",
                              width: "4px",
                              height: "1.25em",
                              backgroundColor: "#4f46e5",
                              marginLeft: "6px",
                              verticalAlign: "middle",
                            }}
                          />
                        )}
                      </span>
                      {line.highlight && (
                        <div
                          style={{
                            position: "absolute",
                            left: -8,
                            right: -8,
                            bottom: 3,
                            height: "64%",
                            backgroundColor: line.highlightColor,
                            opacity: 0.65,
                            zIndex: 1,
                            borderRadius: line.borderRadius,
                            transform: `scaleX(${sweepProgress})`,
                            transformOrigin: "left",
                            transition: "none",
                          }}
                        />
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default EmailNotification;